import{_ as t,o as l,c as n,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Testing Weekly 2018-09-05","description":"","frontmatter":{"title":"Ceph Testing Weekly 2018-09-05","date":"2018-09-05T00:00:00.000Z","updated":"2018-09-06T00:00:00.000Z","tags":["Ceph","分布式存储","测试","自动化","OpenSUSE"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Weekly_2018-09-05.md","filePath":"posts/2018/Ceph_Testing_Weekly_2018-09-05.md","lastUpdated":1780460162000}'),i={name:"posts/2018/Ceph_Testing_Weekly_2018-09-05.md"};function a(s,e,o,r,g,h){return l(),n("div",null,[...e[0]||(e[0]=[p("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Nathan、Greg、Helen等</p><p><strong>会议主题</strong>：</p><ol><li>Ceph存储集群部署测试的进展与问题讨论</li><li>OpenSUSE在Ceph集群测试中的应用</li><li>Ceph集群测试工具的改进与优化</li></ol><p><strong>会议内容</strong>：</p><p><strong>一、Ceph存储集群部署测试的进展与问题讨论</strong></p><ul><li>Nathan在尝试将Ceph集群部署到OpenSUSE时遇到了问题，原因是缺少必要的脚本和配置。</li><li>Greg了解到Nathan曾向Zach寻求帮助，但脚本链接已失效。</li><li>会议决定由Nathan通过邮件联系Zach，获取相关脚本，以便自动化部署。</li></ul><p><strong>二、OpenSUSE在Ceph集群测试中的应用</strong></p><ul><li>Nathan提出将OpenSUSE作为Ceph集群测试的额外支持发行版。</li><li>Greg表示需要创建Fog镜像和OVH镜像，以便在OpenSUSE上运行测试。</li><li>会议决定由Nathan与David Galloway联系，寻求帮助创建Fog镜像。</li></ul><p><strong>三、Ceph集群测试工具的改进与优化</strong></p><ul><li>Nathan提到在OpenSUSE上运行Ceph集群测试时遇到的问题，包括单元测试失败等。</li><li>Greg建议尝试在Ubuntu环境中运行测试，并询问是否已在Ubuntu环境中运行测试。</li><li>会议决定进一步调查测试失败的原因，并尝试在Ubuntu环境中运行测试。</li></ul><p><strong>四、其他事项</strong></p><ul><li>Helen提到Red Hat团队正在使用flake工具分析Ceph代码库，并计划在下周会议上分享他们的发现。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Nathan通过邮件联系Zach，获取相关脚本。</li><li>Nathan与David Galloway联系，寻求帮助创建Fog镜像。</li><li>尝试在Ubuntu环境中运行Ceph集群测试，并调查测试失败的原因。</li><li>准备下周会议，讨论flake工具的分析结果。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了Ceph集群测试工具的一些关键术语，如CML、Ceph-ansible、Jenkins、Tox等。</li><li>会议中提到了Ceph集群测试的一些关键功能，如集群部署、验证、单元测试、集成测试等。</li><li>会议还讨论了Ceph在OpenSUSE上的测试和部署，以及如何改善测试工具和流程。</li></ul>",18)])])}const C=t(i,[["render",a]]);export{u as __pageData,C as default};
